import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadRanehData(){const e=readFileSync(resolve(__dirname,"../../raneh-falls-explorer/raneh-data.js"),"utf-8");return new Function(e+"\nreturn { RANEH_INFO, GEOLOGY_ROCKS, SEASONAL_DATA, NEARBY_ATTRACTIONS, GALLERY_IMAGES, REFERENCES };")()}describe("Raneh Falls Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadRanehData()}),describe("RANEH_INFO metadata",()=>{it("contains correct Raneh Falls location, height, and Ken River source",()=>{expect(e.RANEH_INFO.id).toBe("raneh-falls"),expect(e.RANEH_INFO.title).toContain("Raneh Falls"),expect(e.RANEH_INFO.waterfallHeight).toContain("30 Meters"),expect(e.RANEH_INFO.riverSource).toContain("Ken River")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.RANEH_INFO.quickStats)).toBe(!0),expect(e.RANEH_INFO.quickStats.length).toBe(6)})}),describe("GEOLOGY_ROCKS & SEASONAL_DATA",()=>{it("contains 5-color geology rock strata and seasonal flow data",()=>{expect(Array.isArray(e.GEOLOGY_ROCKS)).toBe(!0),expect(e.GEOLOGY_ROCKS.length).toBeGreaterThanOrEqual(4);const t=e.GEOLOGY_ROCKS.find(e=>e.name.includes("Granite"));expect(t).toBeDefined(),expect(Array.isArray(e.SEASONAL_DATA)).toBe(!0),expect(e.SEASONAL_DATA.length).toBeGreaterThanOrEqual(3)})}),describe("NEARBY_ATTRACTIONS & REFERENCES",()=>{it("contains nearby Khajuraho circuit attractions and references",()=>{expect(Array.isArray(e.NEARBY_ATTRACTIONS)).toBe(!0),expect(e.NEARBY_ATTRACTIONS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});